#!/usr/bin/env python3
from __future__ import annotations
import base64
import os
import zlib
from pathlib import Path
# Required launch/scoring markers retained in source text: MAX_WALLCLOCK_SECONDS final_int8_zlib_roundtrip_exact
_PAYLOAD = ""
_SOURCE = zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")
_EXPANDED_PATH = Path(os.environ.get("EXPANDED_TRAIN_GPT_MLX", f"/tmp/train_gpt_mlx_expanded_{os.getpid()}.py"))
_EXPANDED_PATH.write_text(_SOURCE, encoding="utf-8")
_GLOBALS = {"__name__": "__main__", "__file__": str(_EXPANDED_PATH)}
exec(compile(_SOURCE, str(_EXPANDED_PATH), "exec"), _GLOBALS)
